COPY ayahs (id, surah_id, ayah_number, text_ar, text_ar_plain, page) FROM stdin;
3201	27	42	فَلَمَّا جَاءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ ۖ قَالَتْ كَأَنَّهُ هُوَ ۚ وَأُوتِينَا الْعِلْمَ مِنْ قَبْلِهَا وَكُنَّا مُسْلِمِينَ	فلما جاءت قيل اهكذا عرشك  قالت كانه هو  واوتينا العلم من قبلها وكنا مسلمين	380
3202	27	43	وَصَدَّهَا مَا كَانَتْ تَعْبُدُ مِنْ دُونِ اللَّهِ ۖ إِنَّهَا كَانَتْ مِنْ قَوْمٍ كَافِرِينَ	وصدها ما كانت تعبد من دون الله  انها كانت من قوم كافرين	380
3203	27	44	قِيلَ لَهَا ادْخُلِي الصَّرْحَ ۖ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَنْ سَاقَيْهَا ۚ قَالَ إِنَّهُ صَرْحٌ مُمَرَّدٌ مِنْ قَوَارِيرَ ۗ قَالَتْ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ	قيل لها ادخلي الصرح  فلما راته حسبته لجة وكشفت عن ساقيها  قال انه صرح ممرد من قوارير  قالت رب اني ظلمت نفسي واسلمت مع سليمان لله رب العالمين	380
3204	27	45	وَلَقَدْ أَرْسَلْنَا إِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا أَنِ اعْبُدُوا اللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ	ولقد ارسلنا الي ثمود اخاهم صالحا ان اعبدوا الله فاذا هم فريقان يختصمون	381
3205	27	46	قَالَ يَا قَوْمِ لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِ ۖ لَوْلَا تَسْتَغْفِرُونَ اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ	قال يا قوم لم تستعجلون بالسيئة قبل الحسنة  لولا تستغفرون الله لعلكم ترحمون	381
3206	27	47	قَالُوا اطَّيَّرْنَا بِكَ وَبِمَنْ مَعَكَ ۚ قَالَ طَائِرُكُمْ عِنْدَ اللَّهِ ۖ بَلْ أَنْتُمْ قَوْمٌ تُفْتَنُونَ	قالوا اطيرنا بك وبمن معك  قال طائركم عند الله  بل انتم قوم تفتنون	381
3207	27	48	وَكَانَ فِي الْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِي الْأَرْضِ وَلَا يُصْلِحُونَ	وكان في المدينة تسعة رهط يفسدون في الارض ولا يصلحون	381
3208	27	49	قَالُوا تَقَاسَمُوا بِاللَّهِ لَنُبَيِّتَنَّهُ وَأَهْلَهُ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِ وَإِنَّا لَصَادِقُونَ	قالوا تقاسموا بالله لنبيتنه واهله ثم لنقولن لوليه ما شهدنا مهلك اهله وانا لصادقون	381
3209	27	50	وَمَكَرُوا مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ	ومكروا مكرا ومكرنا مكرا وهم لا يشعرون	381
3210	27	51	فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَاهُمْ وَقَوْمَهُمْ أَجْمَعِينَ	فانظر كيف كان عاقبة مكرهم انا دمرناهم وقومهم اجمعين	381
3211	27	52	فَتِلْكَ بُيُوتُهُمْ خَاوِيَةً بِمَا ظَلَمُوا ۗ إِنَّ فِي ذَٰلِكَ لَآيَةً لِقَوْمٍ يَعْلَمُونَ	فتلك بيوتهم خاوية بما ظلموا  ان في ذلك لاية لقوم يعلمون	381
3212	27	53	وَأَنْجَيْنَا الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ	وانجينا الذين امنوا وكانوا يتقون	381
3213	27	54	وَلُوطًا إِذْ قَالَ لِقَوْمِهِ أَتَأْتُونَ الْفَاحِشَةَ وَأَنْتُمْ تُبْصِرُونَ	ولوطا اذ قال لقومه اتاتون الفاحشة وانتم تبصرون	381
3214	27	55	أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِنْ دُونِ النِّسَاءِ ۚ بَلْ أَنْتُمْ قَوْمٌ تَجْهَلُونَ	ائنكم لتاتون الرجال شهوة من دون النساء  بل انتم قوم تجهلون	381
3215	27	56	۞ فَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَنْ قَالُوا أَخْرِجُوا آلَ لُوطٍ مِنْ قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ	۞ فما كان جواب قومه الا ان قالوا اخرجوا ال لوط من قريتكم  انهم اناس يتطهرون	382
3216	27	57	فَأَنْجَيْنَاهُ وَأَهْلَهُ إِلَّا امْرَأَتَهُ قَدَّرْنَاهَا مِنَ الْغَابِرِينَ	فانجيناه واهله الا امراته قدرناها من الغابرين	382
3217	27	58	وَأَمْطَرْنَا عَلَيْهِمْ مَطَرًا ۖ فَسَاءَ مَطَرُ الْمُنْذَرِينَ	وامطرنا عليهم مطرا  فساء مطر المنذرين	382
3218	27	59	قُلِ الْحَمْدُ لِلَّهِ وَسَلَامٌ عَلَىٰ عِبَادِهِ الَّذِينَ اصْطَفَىٰ ۗ آللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ	قل الحمد لله وسلام علي عباده الذين اصطفي  الله خير اما يشركون	382
3219	27	60	أَمَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَأَنْزَلَ لَكُمْ مِنَ السَّمَاءِ مَاءً فَأَنْبَتْنَا بِهِ حَدَائِقَ ذَاتَ بَهْجَةٍ مَا كَانَ لَكُمْ أَنْ تُنْبِتُوا شَجَرَهَا ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ	امن خلق السماوات والارض وانزل لكم من السماء ماء فانبتنا به حدائق ذات بهجة ما كان لكم ان تنبتوا شجرها  االه مع الله  بل هم قوم يعدلون	382
3220	27	61	أَمَّنْ جَعَلَ الْأَرْضَ قَرَارًا وَجَعَلَ خِلَالَهَا أَنْهَارًا وَجَعَلَ لَهَا رَوَاسِيَ وَجَعَلَ بَيْنَ الْبَحْرَيْنِ حَاجِزًا ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ	امن جعل الارض قرارا وجعل خلالها انهارا وجعل لها رواسي وجعل بين البحرين حاجزا  االه مع الله  بل اكثرهم لا يعلمون	382
3221	27	62	أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ وَيَجْعَلُكُمْ خُلَفَاءَ الْأَرْضِ ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ قَلِيلًا مَا تَذَكَّرُونَ	امن يجيب المضطر اذا دعاه ويكشف السوء ويجعلكم خلفاء الارض  االه مع الله  قليلا ما تذكرون	382
3222	27	63	أَمَّنْ يَهْدِيكُمْ فِي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ وَمَنْ يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ تَعَالَى اللَّهُ عَمَّا يُشْرِكُونَ	امن يهديكم في ظلمات البر والبحر ومن يرسل الرياح بشرا بين يدي رحمته  االه مع الله  تعالي الله عما يشركون	382
3223	27	64	أَمَّنْ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَمَنْ يَرْزُقُكُمْ مِنَ السَّمَاءِ وَالْأَرْضِ ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ قُلْ هَاتُوا بُرْهَانَكُمْ إِنْ كُنْتُمْ صَادِقِينَ	امن يبدا الخلق ثم يعيده ومن يرزقكم من السماء والارض  االه مع الله  قل هاتوا برهانكم ان كنتم صادقين	383
3224	27	65	قُلْ لَا يَعْلَمُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ ۚ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ	قل لا يعلم من في السماوات والارض الغيب الا الله  وما يشعرون ايان يبعثون	383
3225	27	66	بَلِ ادَّارَكَ عِلْمُهُمْ فِي الْآخِرَةِ ۚ بَلْ هُمْ فِي شَكٍّ مِنْهَا ۖ بَلْ هُمْ مِنْهَا عَمُونَ	بل ادارك علمهم في الاخرة  بل هم في شك منها  بل هم منها عمون	383
3226	27	67	وَقَالَ الَّذِينَ كَفَرُوا أَإِذَا كُنَّا تُرَابًا وَآبَاؤُنَا أَئِنَّا لَمُخْرَجُونَ	وقال الذين كفروا ااذا كنا ترابا واباؤنا ائنا لمخرجون	383
3227	27	68	لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَآبَاؤُنَا مِنْ قَبْلُ إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ	لقد وعدنا هذا نحن واباؤنا من قبل ان هذا الا اساطير الاولين	383
3228	27	69	قُلْ سِيرُوا فِي الْأَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِمِينَ	قل سيروا في الارض فانظروا كيف كان عاقبة المجرمين	383
3229	27	70	وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُنْ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ	ولا تحزن عليهم ولا تكن في ضيق مما يمكرون	383
3230	27	71	وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِنْ كُنْتُمْ صَادِقِينَ	ويقولون متي هذا الوعد ان كنتم صادقين	383
3231	27	72	قُلْ عَسَىٰ أَنْ يَكُونَ رَدِفَ لَكُمْ بَعْضُ الَّذِي تَسْتَعْجِلُونَ	قل عسي ان يكون ردف لكم بعض الذي تستعجلون	383
3232	27	73	وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ	وان ربك لذو فضل علي الناس ولكن اكثرهم لا يشكرون	383
3233	27	74	وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ	وان ربك ليعلم ما تكن صدورهم وما يعلنون	383
3234	27	75	وَمَا مِنْ غَائِبَةٍ فِي السَّمَاءِ وَالْأَرْضِ إِلَّا فِي كِتَابٍ مُبِينٍ	وما من غائبة في السماء والارض الا في كتاب مبين	383
3235	27	76	إِنَّ هَٰذَا الْقُرْآنَ يَقُصُّ عَلَىٰ بَنِي إِسْرَائِيلَ أَكْثَرَ الَّذِي هُمْ فِيهِ يَخْتَلِفُونَ	ان هذا القران يقص علي بني اسرائيل اكثر الذي هم فيه يختلفون	383
3236	27	77	وَإِنَّهُ لَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ	وانه لهدي ورحمة للمؤمنين	384
3237	27	78	إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ بِحُكْمِهِ ۚ وَهُوَ الْعَزِيزُ الْعَلِيمُ	ان ربك يقضي بينهم بحكمه  وهو العزيز العليم	384
3238	27	79	فَتَوَكَّلْ عَلَى اللَّهِ ۖ إِنَّكَ عَلَى الْحَقِّ الْمُبِينِ	فتوكل علي الله  انك علي الحق المبين	384
3239	27	80	إِنَّكَ لَا تُسْمِعُ الْمَوْتَىٰ وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ	انك لا تسمع الموتي ولا تسمع الصم الدعاء اذا ولوا مدبرين	384
3240	27	81	وَمَا أَنْتَ بِهَادِي الْعُمْيِ عَنْ ضَلَالَتِهِمْ ۖ إِنْ تُسْمِعُ إِلَّا مَنْ يُؤْمِنُ بِآيَاتِنَا فَهُمْ مُسْلِمُونَ	وما انت بهادي العمي عن ضلالتهم  ان تسمع الا من يؤمن باياتنا فهم مسلمون	384
3241	27	82	۞ وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَابَّةً مِنَ الْأَرْضِ تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بِآيَاتِنَا لَا يُوقِنُونَ	۞ واذا وقع القول عليهم اخرجنا لهم دابة من الارض تكلمهم ان الناس كانوا باياتنا لا يوقنون	384
3242	27	83	وَيَوْمَ نَحْشُرُ مِنْ كُلِّ أُمَّةٍ فَوْجًا مِمَّنْ يُكَذِّبُ بِآيَاتِنَا فَهُمْ يُوزَعُونَ	ويوم نحشر من كل امة فوجا ممن يكذب باياتنا فهم يوزعون	384
3243	27	84	حَتَّىٰ إِذَا جَاءُوا قَالَ أَكَذَّبْتُمْ بِآيَاتِي وَلَمْ تُحِيطُوا بِهَا عِلْمًا أَمَّاذَا كُنْتُمْ تَعْمَلُونَ	حتي اذا جاءوا قال اكذبتم باياتي ولم تحيطوا بها علما اماذا كنتم تعملون	384
3244	27	85	وَوَقَعَ الْقَوْلُ عَلَيْهِمْ بِمَا ظَلَمُوا فَهُمْ لَا يَنْطِقُونَ	ووقع القول عليهم بما ظلموا فهم لا ينطقون	384
3245	27	86	أَلَمْ يَرَوْا أَنَّا جَعَلْنَا اللَّيْلَ لِيَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا ۚ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِقَوْمٍ يُؤْمِنُونَ	الم يروا انا جعلنا الليل ليسكنوا فيه والنهار مبصرا  ان في ذلك لايات لقوم يؤمنون	384
